def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer(shop):
    res = shop.insights.handle_order_history("nope")
    assert res.status == 404
    assert res.body == {"error": "customer not found"}


def test_customer_without_orders(shop):
    res = shop.insights.handle_order_history("c1")
    assert (res.status, res.body) == (200, {"customer_id": "c1", "orders": []})


def test_history_newest_first_with_discount_and_cancelled(shop):
    first = order(shop, "c1", ("PEN", 1)).body["order_id"]
    second = order(shop, "c1", ("LAMP", 2)).body["order_id"]  # 12000 -> 10% off
    third = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c2", ("BOOK", 1))
    shop.orders.handle_cancel(third)
    res = shop.insights.handle_order_history("c1")
    assert res.status == 200
    assert res.body == {"customer_id": "c1", "orders": [
        {"order_id": third, "status": "cancelled", "total_cents": 2_500},
        {"order_id": second, "status": "placed", "total_cents": 10_800},
        {"order_id": first, "status": "placed", "total_cents": 300},
    ]}
    for entry in res.body["orders"]:
        assert entry["total_cents"] == shop.orders.handle_get(entry["order_id"]).body["total_cents"]


