def test_lifetime_value_excludes_cancelled_and_includes_discounts(shop):
    order(shop, "c1", ("PEN", 1))                              # 300
    order(shop, "c1", ("LAMP", 2))                             # 12000 -> 10800
    cancelled = order(shop, "c1", ("BOOK", 4)).body["order_id"]
    order(shop, "c2", ("BOOK", 1))
    shop.orders.handle_cancel(cancelled)
    res = shop.insights.handle_lifetime_value("c1")
