    assert res.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 11_100}
    history = shop.insights.handle_order_history("c1").body["orders"]
    assert res.body["lifetime_value_cents"] == sum(
        e["total_cents"] for e in history if e["status"] != "cancelled")


